<script setup lang="ts">
import { nextTick, onBeforeUnmount, ref, watch } from 'vue'
import { storeToRefs } from 'pinia'

import CreateCustomerModal from '../components/customers/CreateCustomerModal.vue'
import CustomerMobileCards from '../components/customers/CustomerMobileCards.vue'
import CustomerTable from '../components/customers/CustomerTable.vue'
import { useCustomerStore } from '../stores/customer'
import type { CreateCustomerInput } from '../types/customer'

const customerStore = useCustomerStore()
const { filteredCustomers, industries, industryFilter, searchQuery, sortBy, statistics, statusFilter } = storeToRefs(customerStore)
const createModalOpen = ref(false)
const createButton = ref<HTMLButtonElement | null>(null)
const feedback = ref('')
let feedbackTimer: number | undefined

function showFeedback(message: string) { feedback.value = message; if (feedbackTimer) window.clearTimeout(feedbackTimer); feedbackTimer = window.setTimeout(() => { feedback.value = '' }, 4000) }
function closeModal() { createModalOpen.value = false; void nextTick(() => createButton.value?.focus()) }
function createCustomer(input: CreateCustomerInput) { const customer = customerStore.createCustomer(input); showFeedback(`已新增客戶「${customer.companyName}」。`); closeModal() }
watch(createModalOpen, (isOpen) => document.body.classList.toggle('has-modal-open', isOpen))
onBeforeUnmount(() => { document.body.classList.remove('has-modal-open'); if (feedbackTimer) window.clearTimeout(feedbackTimer) })
</script>

<template>
  <div class="customers-view"><header class="customers-view__header"><div><p>TaskFlow</p><h1>客戶</h1><span>集中管理客戶資料與合作關係。</span></div><button ref="createButton" type="button" @click="createModalOpen = true">＋ 新增客戶</button></header><section class="customers-summary" aria-label="客戶摘要"><dl><div><dt>全部客戶</dt><dd>{{ statistics.total }}</dd></div><div><dt>潛在客戶</dt><dd>{{ statistics.lead }}</dd></div><div><dt>合作中</dt><dd>{{ statistics.active }}</dd></div><div><dt>暫停合作</dt><dd>{{ statistics.inactive }}</dd></div></dl></section><section class="customers-toolbar" aria-label="客戶篩選"><label>搜尋客戶<input v-model="searchQuery" placeholder="公司、聯絡人或電子郵件" /></label><label>狀態<select v-model="statusFilter"><option value="all">全部</option><option value="lead">潛在客戶</option><option value="active">合作中</option><option value="inactive">暫停合作</option></select></label><label>產業<select v-model="industryFilter"><option value="all">全部產業</option><option v-for="industry in industries" :key="industry" :value="industry">{{ industry }}</option></select></label><label>排序<select v-model="sortBy"><option value="last-contact">最後聯絡</option><option value="created">建立日期</option><option value="company">客戶名稱</option></select></label></section><div v-if="feedback" aria-atomic="true" aria-live="polite" class="customers-view__toast" role="status">{{ feedback }}</div><template v-if="filteredCustomers.length"><CustomerTable :customers="filteredCustomers" /><CustomerMobileCards :customers="filteredCustomers" /></template><section v-else class="customers-empty" aria-label="沒有符合條件的客戶"><h2>找不到符合條件的客戶</h2><p>請調整搜尋關鍵字或篩選條件。</p><button type="button" @click="customerStore.clearFilters()">清除篩選</button></section><CreateCustomerModal v-if="createModalOpen" @close="closeModal" @create="createCustomer" /></div>
</template>

<style scoped>
.customers-view { display: grid; gap: var(--space-5); }.customers-view__header { align-items: flex-end; display: flex; gap: var(--space-5); justify-content: space-between; padding: var(--space-2) 0 var(--space-3); }.customers-view__header p, h1, .customers-view__header span { margin: 0; }.customers-view__header p { color: var(--color-accent-strong); font-size: .75rem; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; }h1 { color: var(--color-text); font-size: clamp(1.875rem, 4vw, 2.5rem); letter-spacing: -.045em; line-height: 1.1; margin-top: var(--space-2); }.customers-view__header span { color: var(--color-text-secondary); display: block; font-size: .9375rem; line-height: 1.65; margin-top: var(--space-3); }.customers-view__header button, .customers-empty button { background: var(--color-accent); border: 1px solid var(--color-accent); border-radius: var(--radius-md); color: white; font: inherit; font-weight: 700; min-height: 2.75rem; padding: 0 var(--space-4); }.customers-summary, .customers-toolbar { background: var(--color-surface); border: 1px solid var(--color-border); border-radius: var(--radius-lg); box-shadow: var(--shadow-sm); }.customers-summary { padding: var(--space-4) var(--space-5); }dl { display: grid; gap: var(--space-4); grid-template-columns: repeat(4, minmax(0, 1fr)); margin: 0; }dt { color: var(--color-text-muted); font-size: .75rem; font-weight: 700; }dd { color: var(--color-text); font-size: 1.375rem; font-variant-numeric: tabular-nums; font-weight: 750; margin: var(--space-1) 0 0; }.customers-toolbar { display: grid; gap: var(--space-3); grid-template-columns: minmax(0, 1.4fr) repeat(3, minmax(9rem, .6fr)); padding: var(--space-4); }label { color: var(--color-text-secondary); display: grid; font-size: .75rem; font-weight: 700; gap: var(--space-1); }input, select { background: var(--color-surface); border: 1px solid var(--color-border); border-radius: var(--radius-md); color: var(--color-text); font: inherit; min-height: 2.5rem; padding: 0 var(--space-3); }input:focus-visible, select:focus-visible { border-color: var(--color-accent); outline: 3px solid #c7d2fe; outline-offset: 1px; }.customers-empty { background: var(--color-surface); border: 1px dashed var(--color-border); border-radius: var(--radius-lg); padding: clamp(2rem, 8vw, 4rem); text-align: center; }.customers-empty h2, .customers-empty p { margin: 0; }.customers-empty h2 { color: var(--color-text); font-size: 1.125rem; }.customers-empty p { color: var(--color-text-muted); margin-top: var(--space-2); }.customers-empty button { margin-top: var(--space-5); }.customers-view__toast { background: var(--color-text); border-radius: var(--radius-md); bottom: var(--space-5); box-shadow: var(--shadow-lg); color: white; font-size: .8125rem; max-width: min(24rem, calc(100vw - 2rem)); padding: var(--space-3) var(--space-4); position: fixed; right: var(--space-5); z-index: 30; }@media (max-width: 62rem) { .customers-toolbar { grid-template-columns: repeat(2, minmax(0, 1fr)); } }@media (max-width: 44rem) { .customers-view__header { align-items: flex-start; flex-direction: column; }.customers-toolbar { grid-template-columns: minmax(0, 1fr); }dl { grid-template-columns: repeat(2, minmax(0, 1fr)); } }@media (max-width: 34rem) { .customers-view__header button { width: 100%; }.customers-view__toast { bottom: var(--space-4); left: var(--space-4); right: var(--space-4); } }
</style>
